From ed5c3d49121f87c3f185d1e7fee7b66f4f3b7882 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:10:08 +0100
Subject: [PATCH] applets/systemtray: show quick toggles in the expanded view

Turning notifications or Bluetooth on and off from the expanded System
Tray meant opening the widget first. Widgets can now set a "quick
toggle" action that the tray shows as a switch, as Notifications does.

BUG: 460125
---
 applets/notifications/main.qml          | 11 +++++++++
 applets/systemtray/qml/AbstractItem.qml | 31 +++++++++++++++++++++++++
 applets/systemtray/qml/PlasmoidItem.qml |  9 +++++++
 3 files changed, 51 insertions(+)

diff --git a/applets/notifications/main.qml b/applets/notifications/main.qml
index 8d98753eca..c7771dca23 100644
--- a/applets/notifications/main.qml
+++ b/applets/notifications/main.qml
@@ -270,6 +270,16 @@ PlasmoidItem {
         onTriggered: KCMUtils.KCMLauncher.openSystemSettings("kcm_notifications");
     }

+    // Shown as a switch in the System Tray, so it's checked when Do Not Disturb mode is off
+    PlasmaCore.Action {
+        id: showNotificationsAction
+        text: i18nc("@option:check opposite of Do Not Disturb mode", "Show notifications")
+        icon.name: "notifications"
+        checkable: true
+        checked: !Notifications.Globals.inhibited
+        onTriggered: Notifications.Globals.toggleDoNotDisturbMode()
+    }
+
     Component.onCompleted: {
         Notifications.Globals.adopt(root);

@@ -277,6 +287,7 @@ PlasmoidItem {
         // "Configure" button open the KCM instead, like we do in the Bluetooth
         // and Networks applets
         Plasmoid.setInternalAction("configure", configureAction)
+        Plasmoid.setInternalAction("quick toggle", showNotificationsAction)
     }
     Component.onDestruction: {
         Notifications.Globals.forget(root);
diff --git a/applets/systemtray/qml/AbstractItem.qml b/applets/systemtray/qml/AbstractItem.qml
index 007e62cc6d..ebc17f3b95 100644
--- a/applets/systemtray/qml/AbstractItem.qml
+++ b/applets/systemtray/qml/AbstractItem.qml
@@ -38,6 +38,9 @@ PlasmaCore.ToolTipArea {

     property bool effectivePressed: false

+    // checkable action shown as a switch next to the item in the hidden layout
+    property PlasmaCore.Action quickToggleAction: null
+
     // Keep these in sync with HiddenItems.qml
     readonly property int margins: Kirigami.Units.smallSpacing
     readonly property int maxTextLines: 2
@@ -101,6 +104,7 @@ PlasmaCore.ToolTipArea {
     RowLayout {
         anchors.fill: abstractItem
         anchors.margins: abstractItem.inHiddenLayout ? abstractItem.margins : 0
+        anchors.rightMargin: anchors.margins + (quickToggle.visible ? quickToggle.width + spacing : 0)

         spacing: Kirigami.Units.smallSpacing

@@ -193,4 +197,31 @@ PlasmaCore.ToolTipArea {
             }
         }
     }
+
+    PlasmaComponents3.Switch {
+        id: quickToggle
+
+        // Needs to be above the MouseArea, which covers the applet in the hidden layout
+        z: 2
+        anchors {
+            right: abstractItem.right
+            rightMargin: abstractItem.margins
+            verticalCenter: abstractItem.verticalCenter
+        }
+        visible: abstractItem.inHiddenLayout && (abstractItem.quickToggleAction?.visible ?? false)
+        enabled: abstractItem.quickToggleAction?.enabled ?? false
+        checked: abstractItem.quickToggleAction?.checked ?? false
+        focusPolicy: Qt.NoFocus
+
+        Accessible.name: abstractItem.quickToggleAction?.text ?? ""
+
+        onToggled: {
+            abstractItem.quickToggleAction.trigger();
+            checked = Qt.binding(() => abstractItem.quickToggleAction?.checked ?? false);
+        }
+
+        PlasmaComponents3.ToolTip.text: Accessible.name
+        PlasmaComponents3.ToolTip.visible: hovered
+        PlasmaComponents3.ToolTip.delay: Kirigami.Units.toolTipDelay
+    }
 }
diff --git a/applets/systemtray/qml/PlasmoidItem.qml b/applets/systemtray/qml/PlasmoidItem.qml
index bbefd007b5..7ad8a5a4fe 100644
--- a/applets/systemtray/qml/PlasmoidItem.qml
+++ b/applets/systemtray/qml/PlasmoidItem.qml
@@ -120,7 +120,12 @@ AbstractItem {
         }
     }

+    function updateQuickToggleAction() {
+        quickToggleAction = applet?.Plasmoid.internalAction("quick toggle") ?? null
+    }
+
     onAppletChanged: {
+        updateQuickToggleAction()
         if (applet) {
             applet.parent = iconContainer
             applet.anchors.fill = applet.parent
@@ -153,6 +158,10 @@ AbstractItem {
     Connections {
         target: plasmoidContainer.applet?.Plasmoid ?? null

+        function onInternalActionsChanged() {
+            plasmoidContainer.updateQuickToggleAction()
+        }
+
         //activation using global keyboard shortcut
         function onActivated() {
             plasmoidContainer.effectivePressed = true;
-- 
